import{_ as a,o as e,c as o,ag as r}from"./chunks/framework.CAXxHpAX.js";const q=JSON.parse('{"title":"涅槃","description":"","frontmatter":{},"headers":[],"relativePath":"50-概念资料/dict-涅槃.md","filePath":"50-概念资料/dict-涅槃.md","lastUpdated":1778155802000}'),l={name:"50-概念资料/dict-涅槃.md"};function i(d,t,h,u,n,c){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="涅槃" tabindex="-1">涅槃 <a class="header-anchor" href="#涅槃" aria-label="Permalink to &quot;涅槃&quot;">​</a></h1><blockquote><p>传统：佛家 | 道家对应：归根 | 儒家对应：至善</p></blockquote><h2 id="定义" tabindex="-1">定义 <a class="header-anchor" href="#定义" aria-label="Permalink to &quot;定义&quot;">​</a></h2><p>涅槃（梵语 Nirvana）意为&quot;寂灭&quot;&quot;圆寂&quot;。了空居士对涅槃的理解非常平实——<strong>心无挂碍，远离颠倒梦想</strong>。</p><h2 id="了空居士原话" tabindex="-1">了空居士原话 <a class="header-anchor" href="#了空居士原话" aria-label="Permalink to &quot;了空居士原话&quot;">​</a></h2><blockquote><p>&quot;远离颠倒梦想，究竟涅槃——把颠倒了的人生观转过来，就究竟安宁了。&quot;</p></blockquote><blockquote><p>&quot;心无挂碍——心里没有牵挂和障碍。挂碍是什么？是你放不下的事、放不下的人。心无挂碍了，就远离颠倒梦想。&quot;</p></blockquote><blockquote><p>&quot;照见五蕴皆空，度一切苦厄——这就是涅槃。&quot;</p></blockquote><h2 id="了空居士的独特诠释" tabindex="-1">了空居士的独特诠释 <a class="header-anchor" href="#了空居士的独特诠释" aria-label="Permalink to &quot;了空居士的独特诠释&quot;">​</a></h2><p>了空居士不太讲死后涅槃的高深理论，而是强调<strong>现世涅槃</strong>——在日常生活中做到心无挂碍。涅槃不是一个遥远的境界，而是<strong>放下那一刻的清凉</strong>。</p><blockquote><p>&quot;因上精进，果上随缘就是中观。&quot;——这种心态就是现世的涅槃。</p></blockquote><h2 id="常见误解" tabindex="-1">常见误解 <a class="header-anchor" href="#常见误解" aria-label="Permalink to &quot;常见误解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>正解</th></tr></thead><tbody><tr><td>涅槃是死后才达到的</td><td>当下心无挂碍即是涅槃</td></tr><tr><td>涅槃就是什么都没有了</td><td>涅槃是放下执着，不是否定存在</td></tr><tr><td>涅槃了就不用做事了</td><td>通达无我法不是什么都不做</td></tr></tbody></table><h2 id="相关概念" tabindex="-1">相关概念 <a class="header-anchor" href="#相关概念" aria-label="Permalink to &quot;相关概念&quot;">​</a></h2><ul><li><a href="/50-概念资料/dict-菩提">菩提</a> — 到涅槃的路径</li><li><a href="/50-概念资料/dict-清净心">清净心</a> — 涅槃的心态</li></ul><h2 id="相关模型" tabindex="-1">相关模型 <a class="header-anchor" href="#相关模型" aria-label="Permalink to &quot;相关模型&quot;">​</a></h2><ul><li><a href="/10-核心模型/model-圆融中和">圆融中和</a> — 不偏不倚的涅槃实修</li></ul><h2 id="修行实践" tabindex="-1">修行实践 <a class="header-anchor" href="#修行实践" aria-label="Permalink to &quot;修行实践&quot;">​</a></h2><ul><li>不把涅槃想象成遥远的终点</li><li>当下放下一个挂碍，就是涅槃的一刻</li><li>多做减法——少一分执着，多一分涅槃</li></ul>',19)])])}const b=a(l,[["render",i]]);export{q as __pageData,b as default};
